from pathlib import Path
import json
from flask import Flask,render_template_string
R=Path(__file__).parent; app=Flask(__name__)
P='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AI岗位需求分析</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#202934;font-family:"Microsoft YaHei"}.head{background:#16324f;color:white}.in,.wrap{max-width:1200px;margin:auto;padding:28px}.head h1{margin:0 0 8px}.head p{margin:0;color:#c7d5e5}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:white;border:1px solid #dde3ea;border-radius:8px;padding:20px}.n{font-size:30px;font-weight:bold;color:#087f8c;margin-top:8px}.sub{color:#697586;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.panel h2{font-size:18px;margin:0 0 16px}.row{display:grid;grid-template-columns:100px 1fr 30px;gap:8px;align-items:center;margin:10px 0}.bar{height:9px;background:#edf1f5}.fill{height:100%;background:#e76f51}.tag{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #edf0f4}.wide{margin-top:18px}input{width:100%;padding:11px;border:1px solid #ccd5df;border-radius:5px;margin-bottom:12px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:11px;border-bottom:1px solid #edf0f4;text-align:left}th{background:#f7f9fb}.tablewrap{overflow:auto;max-height:580px}@media(max-width:760px){.cards,.grid{grid-template-columns:1fr}}</style><header class="head"><div class="in"><h1>人工智能岗位需求分析系统</h1><p>{{s.source}} · {{s.keywords}} · {{s.collected_at}}</p></div></header><main class="wrap"><div class="cards"><div class="card"><span class="sub">有效岗位</span><div class="n">{{s.job_count}}</div></div><div class="card"><span class="sub">覆盖城市</span><div class="n">{{s.city_count}}</div></div><div class="card"><span class="sub">平均日薪</span><div class="n">{{s.avg_salary}} 元</div></div><div class="card"><span class="sub">有效薪资样本</span><div class="n">{{s.salary_count}}</div></div></div><div class="grid"><section class="panel"><h2>城市岗位分布</h2>{% set m=s.city_counts[0][1] %}{% for a,b in s.city_counts[:10] %}<div class="row"><span>{{a}}</span><div class="bar"><div class="fill" style="width:{{b/m*100}}%"></div></div><b>{{b}}</b></div>{% endfor %}</section><section class="panel"><h2>搜索方向需求量</h2>{% for a,b in s.keyword_counts %}<div class="tag"><span>{{a}}</span><b>{{b}} 条</b></div>{% endfor %}<h2 style="margin-top:22px">岗位标签</h2>{% for a,b in s.tag_counts[:7] %}<div class="tag"><span>{{a}}</span><b>{{b}}</b></div>{% endfor %}</section></div><section class="panel wide"><h2>岗位数据明细（共 {{s.job_count}} 条）</h2><input id="q" placeholder="搜索岗位、公司、城市或方向" oninput="filterRows()"><div class="tablewrap"><table><tr><th>岗位</th><th>公司</th><th>城市</th><th>薪资</th><th>方向</th></tr>{% for j in s.jobs %}<tr class="job"><td>{{j.title}}</td><td>{{j.company}}</td><td>{{j.city}}</td><td>{{j.salary}}</td><td>{{j.keyword}}</td></tr>{% endfor %}</table></div></section></main><script>function filterRows(){let q=document.getElementById('q').value.toLowerCase();document.querySelectorAll('tr.job').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}</script>'''
@app.route('/')
def home(): return render_template_string(P,s=json.loads((R/'data/summary.json').read_text(encoding='utf-8')))
if __name__=='__main__':
    import os
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 5003)))
